// Dart: Calling a REST API with http package
import 'package:http/http.dart' as http;

Future<void> fetchData() async {
  final response = await http.get(
    Uri.parse('https://api.example.com/data'),
  );
  if (response.statusCode == 200) {
    print(response.body);
  }
}

// Dart: Factorial using recursion
int factorial(int n) {
  if (n <= 1) return 1;          // Base case
  return n * factorial(n - 1);   // Recursive call
}

// Dart: A simple class with properties and a method
class Car {
  String brand;
  int speed;

  Car(this.brand, this.speed);

  void describe() {
    print('$brand goes $speed km/h');
  }
}

void main() {
  Car myCar = Car('Toyota', 120);
  myCar.describe(); // Output: Toyota goes 120 km/h
}

